-- -----------------------------------------------------------
-- Table: cims_appointments
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_appointments`;
CREATE TABLE `cims_appointments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `client_id` bigint(20) unsigned DEFAULT NULL,
  `client_code` varchar(50) DEFAULT NULL,
  `client_name` varchar(255) DEFAULT NULL,
  `client_email` varchar(255) DEFAULT NULL,
  `client_phone` varchar(30) DEFAULT NULL,
  `primary_attendee_name` varchar(255) DEFAULT NULL,
  `staff_id` bigint(20) unsigned NOT NULL,
  `service_id` bigint(20) unsigned NOT NULL,
  `appointment_date` date NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `duration_hours` int(11) NOT NULL DEFAULT 1,
  `status` varchar(20) NOT NULL DEFAULT 'pending',
  `notes` text DEFAULT NULL,
  `internal_notes` text DEFAULT NULL,
  `is_chargeable` tinyint(1) NOT NULL DEFAULT 0,
  `amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `payment_status` varchar(20) NOT NULL DEFAULT 'unpaid' COMMENT 'unpaid, paid, waived, invoiced',
  `invoice_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Links to Grow CRM invoices',
  `confirmation_sent_at` timestamp NULL DEFAULT NULL,
  `reminder_sent_at` timestamp NULL DEFAULT NULL,
  `cancelled_at` timestamp NULL DEFAULT NULL,
  `cancellation_reason` varchar(500) DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_appt_client` (`client_id`),
  KEY `idx_appt_code` (`client_code`),
  KEY `idx_appt_staff` (`staff_id`),
  KEY `idx_appt_service` (`service_id`),
  KEY `idx_appt_date` (`appointment_date`),
  KEY `idx_appt_status` (`status`),
  KEY `idx_appt_payment` (`payment_status`),
  KEY `idx_appt_date_staff` (`appointment_date`,`staff_id`),
  KEY `idx_appt_date_status` (`appointment_date`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



