-- -----------------------------------------------------------
-- Table: cims_bbbee_population_groups
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_bbbee_population_groups`;
CREATE TABLE `cims_bbbee_population_groups` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `population_code` varchar(30) NOT NULL COMMENT 'System code e.g. AFRICAN, COLOURED',
  `population_name` varchar(100) NOT NULL COMMENT 'Official B-BBEE population group',
  `population_description` varchar(255) NOT NULL COMMENT 'Formal description per B-BBEE / Stats SA',
  `is_black_designated` tinyint(1) DEFAULT 0 COMMENT 'Qualifies as Black under B-BBEE Act',
  `is_minority` tinyint(1) DEFAULT 0 COMMENT 'Minority group indicator (statistical)',
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bbbee_population_code` (`population_code`),
  UNIQUE KEY `uk_bbbee_population_name` (`population_name`),
  KEY `idx_bbbee_population_active` (`is_active`,`is_deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='South African B-BBEE population group master';



-- -----------------------------------------------------------
-- Table: cims_citizenships
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_citizenships`;
CREATE TABLE `cims_citizenships` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `iso2_code` char(2) NOT NULL COMMENT 'ISO 3166-1 alpha-2',
  `iso3_code` char(3) NOT NULL COMMENT 'ISO 3166-1 alpha-3',
  `iso_numeric_code` char(3) NOT NULL COMMENT 'ISO 3166-1 numeric',
  `country_name` varchar(100) NOT NULL,
  `nationality_name` varchar(120) NOT NULL COMMENT 'Demonym / nationality',
  `citizenship_description` varchar(255) DEFAULT NULL,
  `continent` varchar(20) DEFAULT 'Africa',
  `region` varchar(50) DEFAULT NULL COMMENT 'Sub-region (e.g. Southern Africa)',
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_iso2` (`iso2_code`),
  UNIQUE KEY `uk_iso3` (`iso3_code`),
  UNIQUE KEY `uk_iso_numeric` (`iso_numeric_code`),
  UNIQUE KEY `uk_nationality` (`nationality_name`),
  KEY `idx_citizenship_active` (`is_active`,`is_deleted`),
  KEY `idx_continent_region` (`continent`,`region`)
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Citizenship / nationality master data with ISO country codes';



