  `vat_reg_date` date DEFAULT NULL,
  `vat_return_cycle` varchar(50) DEFAULT NULL,
  `vat_cycle` varchar(100) DEFAULT NULL,
  `vat_effect_from` date DEFAULT NULL,
  `cipc_annual_return_date` date DEFAULT NULL,
  `cipc_ar_bo` varchar(10) DEFAULT NULL,
  `cipc_beneficial_ownership_date` date DEFAULT NULL,
  `cipc_no_of_shares` int(11) DEFAULT NULL,
  `sic_code` varchar(20) DEFAULT NULL,
  `nature_of_business` varchar(255) DEFAULT NULL,
  `province_of_trading` varchar(50) DEFAULT NULL,
  `profit_code` varchar(20) DEFAULT NULL,
  `loss_code` varchar(20) DEFAULT NULL,
  `contact_person` varchar(255) DEFAULT NULL,
  `contact_phone` varchar(50) DEFAULT NULL,
  `contact_email` varchar(255) DEFAULT NULL,
  `physical_address` text DEFAULT NULL,
  `postal_address` text DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_client_code` (`client_code`),
  KEY `idx_company_reg` (`company_reg_number`),
  KEY `idx_is_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -----------------------------------------------------------
-- Table: cims_clients_archive
