-- -----------------------------------------------------------
-- Table: cims_communication_channels
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_communication_channels`;
CREATE TABLE `cims_communication_channels` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `channel_code` varchar(30) NOT NULL COMMENT 'EMAIL, SMS, WHATSAPP, CALL',
  `channel_name` varchar(100) NOT NULL,
  `channel_description` varchar(255) NOT NULL,
  `requires_consent` tinyint(1) DEFAULT 1,
  `supports_rich_content` tinyint(1) DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_channel_code` (`channel_code`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Available communication channels';



-- -----------------------------------------------------------
-- Table: cims_communication_escalations
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_communication_escalations`;
CREATE TABLE `cims_communication_escalations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `template_id` bigint(20) unsigned NOT NULL COMMENT 'Original message template',
  `escalate_after_minutes` int(11) NOT NULL COMMENT 'Minutes after which escalation triggers',
  `escalate_channel_id` bigint(20) unsigned NOT NULL,
  `escalate_template_id` bigint(20) unsigned NOT NULL,
  `max_attempts` tinyint(4) DEFAULT 3,
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_escalate_from_template` (`template_id`),
  KEY `fk_escalate_to_template` (`escalate_template_id`),
  KEY `fk_escalate_channel` (`escalate_channel_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Escalation rules if no response is received';


-- -----------------------------------------------------------
-- Table: cims_communication_logs
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_communication_logs`;
CREATE TABLE `cims_communication_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `person_id` bigint(20) unsigned NOT NULL,
  `template_id` bigint(20) unsigned NOT NULL,
  `channel_id` bigint(20) unsigned NOT NULL,
  `delivery_status` varchar(30) NOT NULL COMMENT 'SENT, FAILED, READ',
  `delivery_response` text DEFAULT NULL COMMENT 'Gateway/API response',
  `sent_at` datetime DEFAULT NULL,
  `delivered_at` datetime DEFAULT NULL,
  `read_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_comm_log_person` (`person_id`),
  KEY `idx_comm_log_status` (`delivery_status`),
  KEY `fk_log_template` (`template_id`),
  KEY `fk_log_channel` (`channel_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Logs communication delivery and read status';


-- -----------------------------------------------------------
-- Table: cims_communication_read_receipts
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_communication_read_receipts`;
CREATE TABLE `cims_communication_read_receipts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `communication_log_id` bigint(20) unsigned NOT NULL,
  `channel_id` bigint(20) unsigned NOT NULL,
  `read_detected` tinyint(1) DEFAULT 0,
  `read_at` datetime DEFAULT NULL,
  `detection_method` varchar(50) NOT NULL COMMENT 'PIXEL, WEBHOOK',
  `user_agent` varchar(255) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_read_receipt_log` (`communication_log_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Tracks read receipts for messages';


-- -----------------------------------------------------------
-- Table: cims_communication_sla_rules
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_communication_sla_rules`;
CREATE TABLE `cims_communication_sla_rules` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `applies_to` varchar(30) NOT NULL COMMENT 'CLIENT, STAFF',
  `initial_template_id` bigint(20) unsigned NOT NULL,
  `response_time_minutes` int(11) NOT NULL COMMENT 'Expected response SLA',
  `escalate_template_id` bigint(20) unsigned NOT NULL,
  `escalate_channel_id` bigint(20) unsigned NOT NULL,
  `notify_internal` tinyint(1) DEFAULT 1 COMMENT 'Notify staff on breach',
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_sla_initial_template` (`initial_template_id`),
  KEY `fk_sla_escalate_template` (`escalate_template_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='SLA-based escalation rules for communications';


-- -----------------------------------------------------------
-- Table: cims_communication_templates
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_communication_templates`;
CREATE TABLE `cims_communication_templates` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `template_code` varchar(50) NOT NULL COMMENT 'Unique template identifier',
  `template_name` varchar(150) NOT NULL,
  `channel_id` bigint(20) unsigned NOT NULL,
  `language_id` bigint(20) unsigned NOT NULL,
  `subject` varchar(255) DEFAULT NULL COMMENT 'Used for email',
  `body` text NOT NULL COMMENT 'Template body with merge fields',
  `is_system_template` tinyint(1) DEFAULT 0,
  `is_marketing` tinyint(1) DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_unique` (`template_code`,`channel_id`,`language_id`),
  KEY `fk_template_channel` (`channel_id`),
  KEY `fk_template_language` (`language_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Communication templates per channel and language';



-- -----------------------------------------------------------
