  `company_name` varchar(255) DEFAULT NULL,
  `company_number` varchar(100) DEFAULT NULL,
  `vat_number` varchar(50) DEFAULT NULL,
  `income_tax_number` varchar(50) DEFAULT NULL,
  `paye_number` varchar(50) DEFAULT NULL,
  `sdl_number` varchar(50) DEFAULT NULL,
  `uif_number` varchar(50) DEFAULT NULL,
  `title` varchar(20) DEFAULT NULL,
  `initial` varchar(10) DEFAULT NULL,
  `first_name` varchar(100) DEFAULT NULL,
  `surname` varchar(100) DEFAULT NULL,
  `position` varchar(100) DEFAULT NULL,
  `telephone_number` varchar(30) DEFAULT NULL,
  `mobile_number` varchar(30) DEFAULT NULL,
  `whatsapp_number` varchar(30) DEFAULT NULL,
  `home_number` varchar(30) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `pay_period` varchar(50) DEFAULT NULL,
  `period_id` int(10) unsigned DEFAULT NULL,
  `financial_year` varchar(10) DEFAULT NULL,
  `period_combo` varchar(20) DEFAULT NULL,
  `paye_liability` decimal(15,2) NOT NULL DEFAULT 0.00,
  `sdl_liability` decimal(15,2) NOT NULL DEFAULT 0.00,
  `uif_liability` decimal(15,2) NOT NULL DEFAULT 0.00,
  `penalty` decimal(15,2) NOT NULL DEFAULT 0.00,
  `interest` decimal(15,2) NOT NULL DEFAULT 0.00,
  `other` decimal(15,2) NOT NULL DEFAULT 0.00,
  `tax_payable` decimal(15,2) NOT NULL DEFAULT 0.00,
  `payment_reference` varchar(100) DEFAULT NULL,
  `check_digit` varchar(5) DEFAULT NULL,
  `payment_reference_number` varchar(20) DEFAULT NULL,
  `payment_date` date DEFAULT NULL,
  `payment_type` varchar(50) DEFAULT NULL,
  `payment_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `balance_outstanding` decimal(15,2) NOT NULL DEFAULT 0.00,
  `file_emp201_return` varchar(255) DEFAULT NULL,
  `file_emp201_statement` varchar(255) DEFAULT NULL,
  `file_working_papers` varchar(255) DEFAULT NULL,
  `file_emp201_pack` varchar(255) DEFAULT NULL,
  `emp_201_file` varchar(255) DEFAULT NULL,
  `status` tinyint(4) NOT NULL DEFAULT 1,
  `emp201_status` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `trading_name` varchar(255) DEFAULT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `vdp_agreement` varchar(1) DEFAULT 'N',
  `vdp_application_no` varchar(50) DEFAULT NULL,
  `tax_practitioner_reg_no` varchar(50) DEFAULT NULL,
  `tax_practitioner_tel_no` varchar(30) DEFAULT NULL,
  `eti_indicator` varchar(1) DEFAULT 'N',
  `eti_brought_forward` decimal(15,2) DEFAULT 0.00,
  `eti_calculated` decimal(15,2) DEFAULT 0.00,
  `eti_utilised` decimal(15,2) DEFAULT 0.00,
  `eti_carry_forward` decimal(15,2) DEFAULT 0.00,
  `payroll_liability` decimal(15,2) DEFAULT 0.00,
  `paye_payable` decimal(15,2) DEFAULT 0.00,
  `sdl_payable` decimal(15,2) DEFAULT 0.00,
  `uif_payable` decimal(15,2) DEFAULT 0.00,
  `penalty_interest` decimal(15,2) DEFAULT 0.00,
  `payment_period` varchar(10) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `payment_method` varchar(50) DEFAULT NULL,
  `amount_paid` decimal(15,2) DEFAULT 0.00,
  `payment_ref_no` varchar(255) DEFAULT NULL,
  `file_proof_of_payment` varchar(500) DEFAULT NULL,
  `payment_notes` text DEFAULT NULL,
  `declaration_date` date DEFAULT NULL,
  `prepared_by` varchar(255) DEFAULT NULL,
  `approved_by` varchar(255) DEFAULT NULL,
  `file_emp201_return_uploaded` tinyint(1) DEFAULT 0,
  `file_emp201_statement_uploaded` tinyint(1) DEFAULT 0,
  `file_working_papers_uploaded` tinyint(1) DEFAULT 0,
  `file_emp201_pack_uploaded` tinyint(1) DEFAULT 0,
  `file_proof_of_payment_uploaded` tinyint(1) DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_client_id` (`client_id`),
  KEY `idx_financial_year` (`financial_year`),
  KEY `idx_pay_period` (`pay_period`),
  KEY `idx_status` (`status`),
  KEY `cims_emp201_declarations_emp201_status_index` (`emp201_status`)
) ENGINE=InnoDB AUTO_INCREMENT=184 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



-- -----------------------------------------------------------
