-- -----------------------------------------------------------
-- Table: cims_ethnic_groups
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_ethnic_groups`;
CREATE TABLE `cims_ethnic_groups` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
