  KEY `idx_ethnic_active` (`is_active`,`is_deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Master list of ethnic groups';



-- -----------------------------------------------------------
-- Table: cims_event_participants
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_event_participants`;
CREATE TABLE `cims_event_participants` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `event_id` bigint(20) unsigned NOT NULL,
  `person_id` bigint(20) unsigned NOT NULL,
  `role` varchar(50) DEFAULT NULL COMMENT 'OWNER, ATTENDEE',
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_event_person` (`event_id`,`person_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='People linked to events';


-- -----------------------------------------------------------
-- Table: cims_event_recurrence_rules
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_event_recurrence_rules`;
CREATE TABLE `cims_event_recurrence_rules` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `event_id` bigint(20) unsigned NOT NULL,
  `frequency` varchar(20) NOT NULL COMMENT 'DAILY, WEEKLY, MONTHLY, YEARLY',
  `interval_value` int(11) DEFAULT 1 COMMENT 'Every X units',
  `day_of_week` varchar(20) DEFAULT NULL COMMENT 'MON,TUE,... for weekly',
  `day_of_month` tinyint(4) DEFAULT NULL COMMENT '1–31',
  `month_of_year` tinyint(4) DEFAULT NULL COMMENT '1–12',
  `end_date` date DEFAULT NULL,
  `occurrence_count` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_recurrence_event` (`event_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Recurrence rules for repeating events';



-- -----------------------------------------------------------
-- Table: cims_event_reminder_logs
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_event_reminder_logs`;
CREATE TABLE `cims_event_reminder_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `reminder_id` bigint(20) unsigned NOT NULL,
  `person_id` bigint(20) unsigned DEFAULT NULL,
  `delivery_status` varchar(30) NOT NULL COMMENT 'QUEUED,SENT,FAILED,READ',
  `delivery_response` text DEFAULT NULL,
  `sent_at` datetime DEFAULT NULL,
  `read_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_reminder_log_reminder` (`reminder_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Logs event reminder delivery';


-- -----------------------------------------------------------
-- Table: cims_event_reminders
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_event_reminders`;
CREATE TABLE `cims_event_reminders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `event_id` bigint(20) unsigned NOT NULL,
  `remind_before_minutes` int(11) NOT NULL COMMENT 'e.g. 1440 = 1 day before',
  `channel_id` bigint(20) unsigned NOT NULL,
  `template_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Communication template',
  `escalation_rule_id` bigint(20) unsigned DEFAULT NULL,
  `is_sent` tinyint(1) DEFAULT 0,
  `sent_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_reminder_event` (`event_id`),
  KEY `fk_reminder_channel` (`channel_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Defines reminder timing and delivery channel per event';



-- -----------------------------------------------------------
-- Table: cims_events
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_events`;
CREATE TABLE `cims_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `event_code` varchar(50) DEFAULT NULL COMMENT 'Optional system code',
  `event_name` varchar(150) NOT NULL,
  `event_description` varchar(255) DEFAULT NULL,
  `event_date` date NOT NULL,
  `event_time` time DEFAULT NULL,
  `is_all_day` tinyint(1) DEFAULT 1,
  `event_type` varchar(50) NOT NULL COMMENT 'BIRTHDAY, COMPLIANCE, TASK, CUSTOM',
  `related_entity_type` varchar(50) DEFAULT NULL COMMENT 'PERSON, CLIENT, COMPANY',
  `related_entity_id` bigint(20) unsigned DEFAULT NULL,
  `is_recurring` tinyint(1) DEFAULT 0,
  `status` varchar(30) DEFAULT 'ACTIVE' COMMENT 'ACTIVE, COMPLETED, CANCELLED',
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_event_date` (`event_date`),
  KEY `idx_event_entity` (`related_entity_type`,`related_entity_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Core events table (birthdays, deadlines, tasks, reminders)';



-- -----------------------------------------------------------
-- Table: cims_field_labels
