-- -----------------------------------------------------------
-- Table: cims_payroll_codes
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_codes`;
CREATE TABLE `cims_payroll_codes` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `transaction_code` smallint(5) unsigned NOT NULL COMMENT '4-digit numeric code e.g. 1000, 2010',
  `master_text` varchar(100) DEFAULT NULL,
  `display_text` varchar(255) NOT NULL COMMENT 'Text shown on payslip and reports',
  `section_id` int(10) unsigned NOT NULL COMMENT 'FK to cims_payroll_code_sections',
  `report_group_id` int(10) unsigned DEFAULT NULL COMMENT 'FK to cims_payroll_code_report_groups',
  `calc_group_id` int(10) unsigned DEFAULT NULL COMMENT 'FK to calc groups for calculation grouping',
  `impact` varchar(10) NOT NULL DEFAULT 'positive' COMMENT 'positive or negative impact on payslip',
  `is_uif` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Contributes to UIF calculation base',
  `is_paye` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Taxable / contributes to PAYE base',
  `is_mibco` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'MIBCO related transaction',
  `is_sdl` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Skills Development Levy related',
  `calc_type` varchar(20) NOT NULL DEFAULT 'fixed' COMMENT 'fixed, percentage, unit',
  `calc_basis` varchar(20) DEFAULT NULL COMMENT 'basic, gross, nett - what the percentage is based on',
  `calc_value` decimal(12,4) DEFAULT 0.0000 COMMENT 'Rate or flat amount',
  `calc_percentage` decimal(8,4) DEFAULT 0.0000 COMMENT 'Percentage value e.g. 1.0000 for 1%',
  `max_amount` decimal(12,2) DEFAULT NULL COMMENT 'Maximum cap amount e.g. UIF max 177.12',
  `min_amount` decimal(12,2) DEFAULT NULL COMMENT 'Minimum amount if applicable',
  `rate_factor` decimal(8,4) DEFAULT 0.0000 COMMENT 'Multiplier for hourly rate e.g. 1.5 for overtime',
  `default_hours` decimal(8,2) DEFAULT 0.00,
  `effective_from` date NOT NULL COMMENT 'Start date this code version is valid',
  `effective_to` date DEFAULT NULL COMMENT 'End date - NULL means still current',
  `status` varchar(20) NOT NULL DEFAULT 'Active' COMMENT 'Active, Inactive, Superseded',
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `notes` text DEFAULT NULL COMMENT 'Any additional notes about this code',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_code_effective` (`transaction_code`,`effective_from`),
  KEY `idx_transaction_code` (`transaction_code`),
  KEY `idx_section_id` (`section_id`),
  KEY `idx_report_group_id` (`report_group_id`),
  KEY `idx_status` (`status`),
  KEY `idx_effective` (`effective_from`,`effective_to`),
  KEY `idx_calc_group_id` (`calc_group_id`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



