DROP TABLE IF EXISTS `cims_payroll_income_types`;
CREATE TABLE `cims_payroll_income_types` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `sars_code` varchar(10) DEFAULT NULL,
  `is_taxable` tinyint(1) NOT NULL DEFAULT 1,
  `is_uif_applicable` tinyint(1) NOT NULL DEFAULT 1,
  `description` text DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



-- -----------------------------------------------------------
-- Table: cims_payroll_leave_applications
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_leave_applications`;
CREATE TABLE `cims_payroll_leave_applications` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint(20) unsigned NOT NULL,
  `leave_type_id` bigint(20) unsigned NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `days_requested` decimal(8,2) NOT NULL,
  `reason` text DEFAULT NULL,
  `status` enum('pending','approved','rejected','cancelled') NOT NULL DEFAULT 'pending',
  `approved_by` bigint(20) unsigned DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `rejection_reason` text DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_la_employee` (`employee_id`),
  KEY `idx_la_status` (`status`),
  KEY `idx_la_dates` (`start_date`,`end_date`),
  KEY `fk_la_leave_type` (`leave_type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



-- -----------------------------------------------------------
-- Table: cims_payroll_leave_balances
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_leave_balances`;
CREATE TABLE `cims_payroll_leave_balances` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint(20) unsigned NOT NULL,
  `leave_type_id` bigint(20) unsigned NOT NULL,
  `year` varchar(4) NOT NULL DEFAULT '2026',
  `entitled_days` decimal(8,2) NOT NULL DEFAULT 0.00,
  `taken_days` decimal(8,2) NOT NULL DEFAULT 0.00,
  `pending_days` decimal(8,2) NOT NULL DEFAULT 0.00,
  `carried_forward` decimal(8,2) NOT NULL DEFAULT 0.00,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_emp_year` (`employee_id`,`year`),
  KEY `idx_leave_type` (`leave_type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -----------------------------------------------------------
-- Table: cims_payroll_leave_documents
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_leave_documents`;
CREATE TABLE `cims_payroll_leave_documents` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `leave_transaction_id` bigint(20) unsigned NOT NULL,
  `file_name` varchar(255) NOT NULL,
  `original_name` varchar(255) NOT NULL,
  `file_path` varchar(500) NOT NULL,
  `document_type` varchar(50) NOT NULL DEFAULT 'other',
  `uploaded_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_leave_doc_txn` (`leave_transaction_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -----------------------------------------------------------
-- Table: cims_payroll_leave_transactions
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_leave_transactions`;
CREATE TABLE `cims_payroll_leave_transactions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint(20) unsigned NOT NULL,
  `leave_type_id` bigint(20) unsigned NOT NULL,
  `payroll_period_id` bigint(20) unsigned DEFAULT NULL,
  `transaction_type` enum('opening_balance','accrual','taken','adjustment') NOT NULL,
  `days` decimal(8,2) NOT NULL DEFAULT 0.00,
  `hours` decimal(8,2) NOT NULL DEFAULT 0.00,
  `description` varchar(255) DEFAULT NULL,
  `certificate_received` tinyint(1) NOT NULL DEFAULT 0,
  `certificate_date` date DEFAULT NULL,
  `certificate_type` varchar(50) DEFAULT NULL,
  `certificate_notes` text DEFAULT NULL,
  `leave_date_from` date DEFAULT NULL,
  `leave_date_to` date DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_emp_type` (`employee_id`,`leave_type_id`),
  KEY `idx_period` (`payroll_period_id`)
) ENGINE=InnoDB AUTO_INCREMENT=69 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



-- -----------------------------------------------------------
-- Table: cims_payroll_leave_types
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_leave_types`;
CREATE TABLE `cims_payroll_leave_types` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `code` varchar(20) NOT NULL,
  `days_per_year` decimal(8,2) NOT NULL DEFAULT 0.00,
  `cycle_years` int(11) NOT NULL DEFAULT 1 COMMENT '1=annual, 3=3-year cycle (sick leave)',
  `is_paid` tinyint(1) NOT NULL DEFAULT 1,
  `is_statutory` tinyint(1) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `description` text DEFAULT NULL,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



-- -----------------------------------------------------------
-- Table: cims_payroll_loan_repayments
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_loan_repayments`;
CREATE TABLE `cims_payroll_loan_repayments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `loan_id` bigint(20) unsigned NOT NULL,
  `pay_run_id` bigint(20) unsigned DEFAULT NULL,
  `amount` decimal(12,2) NOT NULL,
  `repayment_date` date NOT NULL,
  `notes` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_rep_loan` (`loan_id`),
  KEY `idx_rep_payrun` (`pay_run_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -----------------------------------------------------------
-- Table: cims_payroll_loans
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_loans`;
CREATE TABLE `cims_payroll_loans` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint(20) unsigned NOT NULL,
  `loan_type` varchar(100) NOT NULL DEFAULT 'General Loan',
  `loan_amount` decimal(12,2) NOT NULL,
  `outstanding_balance` decimal(12,2) NOT NULL,
  `monthly_repayment` decimal(12,2) NOT NULL DEFAULT 0.00,
  `start_date` date NOT NULL,
  `end_date` date DEFAULT NULL,
  `status` enum('active','paid_off','written_off','suspended') NOT NULL DEFAULT 'active',
  `notes` text DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_loan_emp` (`employee_id`),
  KEY `idx_loan_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -----------------------------------------------------------
-- Table: cims_payroll_medical_aid
-- -----------------------------------------------------------
