  PRIMARY KEY (`id`),
  KEY `idx_prli_line` (`pay_run_line_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -----------------------------------------------------------
-- Table: cims_payroll_pay_run_lines
-- -----------------------------------------------------------
