CREATE TABLE `cims_payroll_pay_run_lines` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `pay_run_id` bigint(20) unsigned NOT NULL,
  `employee_id` bigint(20) unsigned NOT NULL,
  `basic_salary` decimal(12,2) NOT NULL DEFAULT 0.00,
  `hourly_rate` decimal(10,2) NOT NULL DEFAULT 0.00,
  `normal_hours` decimal(8,2) NOT NULL DEFAULT 0.00,
  `overtime_15x_hours` decimal(8,2) NOT NULL DEFAULT 0.00,
  `overtime_2x_hours` decimal(8,2) NOT NULL DEFAULT 0.00,
  `sunday_hours` decimal(8,2) NOT NULL DEFAULT 0.00,
  `public_holiday_hours` decimal(8,2) NOT NULL DEFAULT 0.00,
  `gross_pay` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total_income` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total_deductions` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total_employer_contributions` decimal(12,2) NOT NULL DEFAULT 0.00,
  `net_pay` decimal(12,2) NOT NULL DEFAULT 0.00,
  `paye_tax` decimal(12,2) NOT NULL DEFAULT 0.00,
  `uif_employee` decimal(12,2) NOT NULL DEFAULT 0.00,
  `uif_employer` decimal(12,2) NOT NULL DEFAULT 0.00,
  `sdl_employer` decimal(12,2) NOT NULL DEFAULT 0.00,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_payrun_emp` (`pay_run_id`,`employee_id`),
  KEY `idx_prl_payrun` (`pay_run_id`),
  KEY `idx_prl_employee` (`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -----------------------------------------------------------
-- Table: cims_payroll_pay_runs
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_pay_runs`;
CREATE TABLE `cims_payroll_pay_runs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) unsigned NOT NULL,
  `pay_period` varchar(10) NOT NULL,
  `period_start` date NOT NULL,
  `period_end` date NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `status` enum('draft','processed','approved','cancelled') NOT NULL DEFAULT 'draft',
  `total_gross` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_deductions` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_employer_cost` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_net_pay` decimal(14,2) NOT NULL DEFAULT 0.00,
  `employee_count` int(11) NOT NULL DEFAULT 0,
  `processed_at` timestamp NULL DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `approved_by` bigint(20) unsigned DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_pr_company` (`company_id`),
  KEY `idx_pr_period` (`pay_period`),
  KEY `idx_pr_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -----------------------------------------------------------
-- Table: cims_payroll_periods
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_periods`;
CREATE TABLE `cims_payroll_periods` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) unsigned NOT NULL,
  `company_name` varchar(100) NOT NULL,
  `payroll_year_id` bigint(20) unsigned NOT NULL,
  `is_active` int(11) NOT NULL DEFAULT 0,
  `period_number` tinyint(4) NOT NULL COMMENT '1-12',
  `period_month` tinyint(4) NOT NULL COMMENT 'Calendar month 1-12',
  `period_year` int(11) NOT NULL COMMENT 'Calendar year',
  `period_start` date NOT NULL,
  `period_end` date NOT NULL,
  `number_of_weeks` decimal(4,2) NOT NULL DEFAULT 4.00,
  `status` varchar(10) NOT NULL DEFAULT 'future' COMMENT 'future/current/closed',
  `closed_at` timestamp NULL DEFAULT NULL,
  `closed_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_company_year_period` (`company_id`,`payroll_year_id`,`period_number`)
) ENGINE=InnoDB AUTO_INCREMENT=97 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



-- -----------------------------------------------------------
-- Table: cims_payroll_private_ra
-- -----------------------------------------------------------
