  PRIMARY KEY (`id`),
  KEY `cims_payroll_tax_rebates_tax_year_index` (`tax_year`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



-- -----------------------------------------------------------
-- Table: cims_payroll_tax_thresholds
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_tax_thresholds`;
CREATE TABLE `cims_payroll_tax_thresholds` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `tax_year` varchar(10) NOT NULL,
  `age_group` varchar(30) NOT NULL,
  `threshold_amount` decimal(15,2) NOT NULL,
  `is_active` tinyint(4) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `cims_payroll_tax_thresholds_tax_year_index` (`tax_year`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



-- -----------------------------------------------------------
-- Table: cims_payroll_timesheet_entries
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_timesheet_entries`;
CREATE TABLE `cims_payroll_timesheet_entries` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` int(10) unsigned NOT NULL,
  `entry_date` date NOT NULL,
