  `manager_signed_date` date DEFAULT NULL,
  `status` varchar(20) DEFAULT 'draft',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_emp_period` (`employee_id`,`period_month`,`period_year`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



-- -----------------------------------------------------------
-- Table: cims_payroll_timesheet_status_rules
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_timesheet_status_rules`;
CREATE TABLE `cims_payroll_timesheet_status_rules` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `status_code` varchar(50) NOT NULL,
  `label` varchar(100) NOT NULL,
  `hours_rule` varchar(20) DEFAULT 'fixed',
  `default_hours` decimal(5,2) DEFAULT 0.00,
  `counts_as_day` tinyint(4) DEFAULT 0,
  `payroll_code_id` int(10) unsigned DEFAULT NULL,
  `gl_code` varchar(50) DEFAULT NULL,
  `sort_order` int(11) DEFAULT 0,
  `is_active` tinyint(4) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
