) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



-- -----------------------------------------------------------
-- Table: cims_payroll_timesheets
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_timesheets`;
CREATE TABLE `cims_payroll_timesheets` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint(20) unsigned NOT NULL,
  `period_start` date NOT NULL,
  `period_end` date NOT NULL,
  `normal_hours` decimal(8,2) NOT NULL DEFAULT 0.00,
  `overtime_15x_hours` decimal(8,2) NOT NULL DEFAULT 0.00 COMMENT 'OT at 1.5x',
  `overtime_2x_hours` decimal(8,2) NOT NULL DEFAULT 0.00 COMMENT 'OT at 2x',
  `sunday_hours` decimal(8,2) NOT NULL DEFAULT 0.00 COMMENT 'Sunday work',
  `public_holiday_hours` decimal(8,2) NOT NULL DEFAULT 0.00 COMMENT 'Public holiday work',
  `days_worked` decimal(8,2) NOT NULL DEFAULT 0.00,
  `days_absent` decimal(8,2) NOT NULL DEFAULT 0.00,
  `days_leave` decimal(8,2) NOT NULL DEFAULT 0.00,
  `status` enum('draft','submitted','approved') NOT NULL DEFAULT 'draft',
  `notes` text DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_emp_period` (`employee_id`,`period_start`,`period_end`),
  KEY `idx_ts_employee` (`employee_id`),
  KEY `idx_ts_period` (`period_start`,`period_end`),
  KEY `idx_ts_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



-- -----------------------------------------------------------
-- Table: cims_payroll_transaction_items
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_transaction_items`;
CREATE TABLE `cims_payroll_transaction_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `payroll_transaction_id` bigint(20) unsigned NOT NULL,
  `transaction_code` int(10) unsigned DEFAULT NULL,
  `section` varchar(20) NOT NULL COMMENT 'earnings/deductions/contributions/fringe',
  `name` varchar(100) NOT NULL,
  `display_name` varchar(100) DEFAULT NULL,
  `group_type` varchar(20) DEFAULT 'other',
  `calc_rule` varchar(10) NOT NULL DEFAULT 'add',
  `calc_type` varchar(20) NOT NULL DEFAULT 'fixed',
  `calc_basis` varchar(20) DEFAULT NULL,
  `calc_percentage` decimal(10,4) DEFAULT NULL,
  `calc_quantity` decimal(10,4) DEFAULT NULL,
  `hours` decimal(10,4) NOT NULL DEFAULT 0.0000,
  `rate` decimal(14,6) NOT NULL DEFAULT 0.000000,
  `rate_factor` decimal(5,2) DEFAULT 0.00,
  `amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `is_included` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_transaction` (`payroll_transaction_id`),
  KEY `idx_txcode` (`transaction_code`)
) ENGINE=InnoDB AUTO_INCREMENT=4287 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;






-- -----------------------------------------------------------
-- Table: cims_payroll_transactions
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_transactions`;
CREATE TABLE `cims_payroll_transactions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) unsigned NOT NULL,
  `payroll_period_id` bigint(20) unsigned NOT NULL,
  `employee_id` bigint(20) unsigned NOT NULL,
  `basic_salary` decimal(14,2) NOT NULL DEFAULT 0.00,
  `gross_pay` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_deductions` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_contributions` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_fringe` decimal(14,2) NOT NULL DEFAULT 0.00,
  `net_pay` decimal(14,2) NOT NULL DEFAULT 0.00,
  `payslip_status` varchar(15) NOT NULL DEFAULT 'draft' COMMENT 'draft/pending/processed',
  `processed_at` timestamp NULL DEFAULT NULL,
  `processed_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_period_employee` (`payroll_period_id`,`employee_id`)
) ENGINE=InnoDB AUTO_INCREMENT=98 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



-- -----------------------------------------------------------
-- Table: cims_payroll_years
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_payroll_years`;
CREATE TABLE `cims_payroll_years` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) unsigned NOT NULL,
  `tax_year` int(11) NOT NULL COMMENT 'e.g. 2026 means Mar 2025 - Feb 2026',
  `year_start` date NOT NULL,
  `year_end` date NOT NULL,
  `status` varchar(10) NOT NULL DEFAULT 'open' COMMENT 'open/closed',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_company_taxyear` (`company_id`,`tax_year`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



-- -----------------------------------------------------------
-- Table: cims_periods
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_periods`;
CREATE TABLE `cims_periods` (
  `period_id` int(11) NOT NULL AUTO_INCREMENT,
  `period_year` text NOT NULL,
  `period_month` text NOT NULL,
  `period_combo` text NOT NULL,
  `period_display` text NOT NULL,
  `period_group` text NOT NULL,
  `period_blocked` int(11) NOT NULL DEFAULT 0,
  `period_order_pos` int(11) NOT NULL,
  `period_payment_duedate` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`period_id`)
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;



-- -----------------------------------------------------------
-- Table: cims_permit_types
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_permit_types`;
CREATE TABLE `cims_permit_types` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `permit_code` varchar(30) NOT NULL,
  `permit_name` varchar(150) NOT NULL,
  `permit_description` varchar(255) NOT NULL,
  `allows_work` tinyint(1) DEFAULT 0,
  `allows_residence` tinyint(1) DEFAULT 0,
  `requires_expiry` tinyint(1) DEFAULT 1,
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_permit_code` (`permit_code`),
  UNIQUE KEY `uk_permit_name` (`permit_name`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Visa and permit types for foreign nationals';



-- -----------------------------------------------------------
-- Table: cims_person_addresses
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_person_addresses`;
CREATE TABLE `cims_person_addresses` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `person_id` bigint(20) unsigned NOT NULL,
  `address_id` bigint(20) unsigned NOT NULL,
  `address_type` varchar(40) NOT NULL COMMENT 'Residential/Postal/Business/Registered/Head Office/Branch/Site/Billing/Shipping',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_person_type` (`person_id`,`address_type`),
  KEY `idx_pa_person` (`person_id`),
  KEY `idx_pa_address` (`address_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- -----------------------------------------------------------
-- Table: cims_person_banks
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_person_banks`;
CREATE TABLE `cims_person_banks` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `person_id` bigint(20) unsigned NOT NULL,
  `bank_name` varchar(80) DEFAULT NULL,
  `bank_branch_name` varchar(80) DEFAULT NULL,
  `bank_branch_code` varchar(20) DEFAULT NULL,
  `bank_account_name` varchar(120) DEFAULT NULL,
  `bank_account_number` varchar(40) DEFAULT NULL,
  `bank_account_type` varchar(40) DEFAULT NULL,
  `bank_swift_code` varchar(20) DEFAULT NULL,
  `bank_date_opened` date DEFAULT NULL,
  `bank_account_status` varchar(20) NOT NULL DEFAULT 'Active',
  `is_primary` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_pb_person` (`person_id`),
  KEY `idx_pb_status` (`bank_account_status`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- -----------------------------------------------------------
-- Table: cims_person_citizenships
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_person_citizenships`;
CREATE TABLE `cims_person_citizenships` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `person_id` bigint(20) unsigned NOT NULL COMMENT 'FK to person / client / employee',
  `citizenship_id` bigint(20) unsigned NOT NULL COMMENT 'FK to cims_citizenships',
  `is_primary` tinyint(1) DEFAULT 0 COMMENT 'Primary citizenship indicator',
  `acquired_method` varchar(50) DEFAULT NULL COMMENT 'Birth, Naturalisation, Descent',
  `acquired_date` date DEFAULT NULL COMMENT 'Date citizenship was acquired',
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_person_citizenship` (`person_id`,`citizenship_id`),
  KEY `idx_person_primary` (`person_id`,`is_primary`),
  KEY `idx_citizenship` (`citizenship_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Link table supporting dual or multiple citizenship per person';


-- -----------------------------------------------------------
-- Table: cims_person_communication_preferences
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_person_communication_preferences`;
CREATE TABLE `cims_person_communication_preferences` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `person_id` bigint(20) unsigned NOT NULL,
  `channel_id` bigint(20) unsigned NOT NULL,
  `language_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Preferred language for this channel',
  `is_preferred` tinyint(1) DEFAULT 0 COMMENT 'Primary communication channel',
  `is_allowed` tinyint(1) DEFAULT 1 COMMENT 'Channel may be used',
  `consent_given` tinyint(1) DEFAULT 0,
  `consent_date` date DEFAULT NULL,
  `consent_source` varchar(100) DEFAULT NULL COMMENT 'Contract, form, email, verbal',
  `quiet_hours_start` time DEFAULT NULL COMMENT 'Do not contact before',
  `quiet_hours_end` time DEFAULT NULL COMMENT 'Do not contact after',
  `fallback_order` tinyint(4) DEFAULT NULL COMMENT 'Lower number = higher priority',
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_person_channel` (`person_id`,`channel_id`),
  KEY `idx_person_comm_pref` (`person_id`,`is_preferred`),
  KEY `fk_comm_pref_channel` (`channel_id`),
  KEY `fk_comm_pref_language` (`language_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Communication preferences and rules per person';



-- -----------------------------------------------------------
-- Table: cims_person_ethnic_groups
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_person_ethnic_groups`;
CREATE TABLE `cims_person_ethnic_groups` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `person_id` bigint(20) unsigned NOT NULL,
  `ethnic_group_id` bigint(20) unsigned NOT NULL,
  `is_primary` tinyint(1) DEFAULT 1,
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_person_ethnic` (`person_id`,`ethnic_group_id`),
  KEY `fk_person_ethnic_group` (`ethnic_group_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Links a person to their ethnic group';


-- -----------------------------------------------------------
-- Table: cims_person_languages
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_person_languages`;
CREATE TABLE `cims_person_languages` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `person_id` bigint(20) unsigned NOT NULL,
  `language_id` bigint(20) unsigned NOT NULL,
  `proficiency_level` varchar(30) NOT NULL COMMENT 'Basic, Intermediate, Fluent, Native',
  `is_home_language` tinyint(1) DEFAULT 0,
  `is_preferred_language` tinyint(1) DEFAULT 0,
  `can_read` tinyint(1) DEFAULT 1,
  `can_write` tinyint(1) DEFAULT 1,
  `can_speak` tinyint(1) DEFAULT 1,
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_person_language` (`person_id`,`language_id`),
  KEY `idx_person_language_pref` (`person_id`,`is_preferred_language`),
  KEY `fk_person_language_language` (`language_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Tracks multiple languages per person with proficiency and preference';



-- -----------------------------------------------------------
-- Table: cims_person_notification_preferences
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_person_notification_preferences`;
CREATE TABLE `cims_person_notification_preferences` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `person_id` bigint(20) unsigned NOT NULL,
  `allow_system_alerts` tinyint(1) DEFAULT 1 COMMENT 'Compliance, reminders',
  `allow_transactional` tinyint(1) DEFAULT 1 COMMENT 'Invoices, statements',
  `allow_marketing` tinyint(1) DEFAULT 0 COMMENT 'Marketing messages',
  `marketing_consent_date` date DEFAULT NULL,
  `consent_source` varchar(100) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_person_notification` (`person_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Controls notification and marketing preferences per person';


-- -----------------------------------------------------------
-- Table: cims_person_status_history
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_person_status_history`;
CREATE TABLE `cims_person_status_history` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `person_id` bigint(20) unsigned NOT NULL,
  `person_status_id` bigint(20) unsigned NOT NULL,
  `status_date` date DEFAULT NULL COMMENT 'Date status became effective',
  `notes` varchar(255) DEFAULT NULL,
  `is_current` tinyint(1) DEFAULT 1,
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_person_status_current` (`person_id`,`is_current`),
  KEY `fk_person_status_history_status` (`person_status_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Tracks status history of a person';


-- -----------------------------------------------------------
-- Table: cims_person_statuses
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_person_statuses`;
CREATE TABLE `cims_person_statuses` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `status_code` varchar(30) NOT NULL COMMENT 'System code e.g. ALIVE, DECEASED',
  `status_name` varchar(100) NOT NULL COMMENT 'Display name',
  `status_description` varchar(255) DEFAULT NULL COMMENT 'Human-readable explanation',
  `is_terminal` tinyint(1) DEFAULT 0 COMMENT 'If true, no further actions allowed',
  `requires_date` tinyint(1) DEFAULT 0 COMMENT 'Requires a status date (e.g. date of death)',
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_person_status_code` (`status_code`),
  UNIQUE KEY `uk_person_status_name` (`status_name`),
  KEY `idx_person_status_active` (`is_active`,`is_deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Master table defining the life/status of a person';



-- -----------------------------------------------------------
-- Table: cims_persons
-- -----------------------------------------------------------
