  `tax_number` varchar(20) DEFAULT NULL,
  `mobile_phone` varchar(20) DEFAULT NULL,
  `whatsapp_number` varchar(20) DEFAULT NULL,
  `office_phone` varchar(20) DEFAULT NULL,
  `other_phone` varchar(20) DEFAULT NULL,
  `business_phone` varchar(20) DEFAULT NULL,
  `home_phone` varchar(20) DEFAULT NULL,
  `direct_number` varchar(20) DEFAULT NULL,
  `email` varchar(120) DEFAULT NULL,
  `accounts_email` varchar(120) DEFAULT NULL,
  `sars_tax_number` varchar(20) DEFAULT NULL,
  `sars_login_name` varchar(120) DEFAULT NULL,
  `sars_login_password` varchar(120) DEFAULT NULL,
  `sars_cell_number` varchar(20) DEFAULT NULL,
  `sars_email_address` varchar(120) DEFAULT NULL,
  `marital_status` varchar(40) DEFAULT NULL,
  `marital_status_date` date DEFAULT NULL,
  `spouse_id_number` varchar(20) DEFAULT NULL,
  `spouse_gender` varchar(10) DEFAULT NULL,
  `spouse_title` varchar(10) DEFAULT NULL,
  `spouse_initials` varchar(10) DEFAULT NULL,
  `spouse_name` varchar(80) DEFAULT NULL,
  `spouse_surname` varchar(80) DEFAULT NULL,
  `spouse_marriage_type` varchar(40) DEFAULT NULL,
