  `address_line` varchar(200) DEFAULT NULL,
  `address_line_2` varchar(200) DEFAULT NULL,
  `suburb` varchar(80) DEFAULT NULL,
  `city` varchar(80) DEFAULT NULL,
  `postal_code` varchar(10) DEFAULT NULL,
  `province` varchar(40) DEFAULT NULL,
  `address_country` varchar(80) DEFAULT 'South Africa',
  `latitude` varchar(30) DEFAULT NULL,
  `longitude` varchar(30) DEFAULT NULL,
  `bank_account_holder` varchar(120) DEFAULT NULL,
  `bank_name` varchar(80) DEFAULT NULL,
  `bank_branch_name` varchar(80) DEFAULT NULL,
  `bank_branch` varchar(20) DEFAULT NULL,
  `bank_branch_code` varchar(20) DEFAULT NULL,
  `bank_account_name` varchar(120) DEFAULT NULL,
  `bank_account_number` varchar(40) DEFAULT NULL,
  `bank_account_type` varchar(40) DEFAULT NULL,
  `bank_swift_code` varchar(20) DEFAULT NULL,
  `bank_date_opened` date DEFAULT NULL,
  `bank_account_status` varchar(20) DEFAULT NULL,
  `profile_picture` varchar(255) DEFAULT NULL,
  `signature_upload` varchar(255) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `sp_citizenship` varchar(40) DEFAULT NULL,
  `sp_identity_type` varchar(40) DEFAULT NULL,
  `sp_identity_number` varchar(20) DEFAULT NULL,
  `sp_date_of_birth` date DEFAULT NULL,
  `sp_date_of_issue` date DEFAULT NULL,
  `sp_person_status` varchar(20) DEFAULT NULL,
  `sp_gender` varchar(10) DEFAULT NULL,
  `sp_ethnic_group` varchar(40) DEFAULT NULL,
  `sp_disability` varchar(20) DEFAULT NULL,
  `sp_title` varchar(10) DEFAULT NULL,
  `sp_initials` varchar(10) DEFAULT NULL,
  `sp_tax_number` varchar(20) DEFAULT NULL,
  `sp_firstname` varchar(80) DEFAULT NULL,
  `sp_middlename` varchar(80) DEFAULT NULL,
  `sp_surname` varchar(80) DEFAULT NULL,
  `sp_known_as` varchar(80) DEFAULT NULL,
  `sp_mobile_phone` varchar(20) DEFAULT NULL,
  `sp_whatsapp_number` varchar(20) DEFAULT NULL,
  `sp_office_phone` varchar(20) DEFAULT NULL,
  `sp_other_phone` varchar(20) DEFAULT NULL,
  `sp_email` varchar(120) DEFAULT NULL,
  `sp_accounts_email` varchar(120) DEFAULT NULL,
  `sp_country` varchar(80) DEFAULT NULL,
  `sp_country_code` varchar(10) DEFAULT NULL,
  `sp_nationality` varchar(80) DEFAULT NULL,
  `sp_date_of_death` date DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` varchar(80) DEFAULT NULL,
