-- -----------------------------------------------------------
-- Table: cims_share_certificates
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_share_certificates`;
CREATE TABLE `cims_share_certificates` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `client_id` bigint(20) unsigned NOT NULL COMMENT 'FK to client_master.client_id',
  `director_id` bigint(20) unsigned DEFAULT NULL COMMENT 'FK to client_master_directors.id',
  `person_id` bigint(20) unsigned DEFAULT NULL COMMENT 'FK to cims_persons.id',
  `certificate_number` varchar(50) NOT NULL COMMENT 'Sequential per company e.g. SC-001',
  `share_class` varchar(100) DEFAULT 'Ordinary Shares',
  `number_of_shares` int(10) unsigned NOT NULL DEFAULT 0,
  `percentage` decimal(8,4) DEFAULT 0.0000,
  `date_issued` date DEFAULT NULL,
  `date_ceased` date DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `notes` text DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sc_client` (`client_id`),
  KEY `idx_sc_director` (`director_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


