-- -----------------------------------------------------------
-- Table: cims_template_merge_fields
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `cims_template_merge_fields`;
CREATE TABLE `cims_template_merge_fields` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `field_code` varchar(50) NOT NULL COMMENT 'e.g. first_name, due_date',
  `field_label` varchar(100) NOT NULL COMMENT 'Human readable name',
  `field_description` varchar(255) NOT NULL,
  `source_table` varchar(100) NOT NULL COMMENT 'e.g. cims_people',
  `source_column` varchar(100) NOT NULL COMMENT 'e.g. first_name',
  `data_type` varchar(30) NOT NULL COMMENT 'string, date, number',
  `format_hint` varchar(50) DEFAULT NULL COMMENT 'e.g. dd/mm/yyyy',
  `is_sensitive` tinyint(1) DEFAULT 0 COMMENT 'POPIA sensitive field',
  `is_active` tinyint(1) DEFAULT 1,
  `is_deleted` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_merge_field_code` (`field_code`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Registry of allowed merge fields for communication templates';



-- -----------------------------------------------------------
-- Table: cims_titles
