INSERT INTO `cims_email_templates` (`id`, `name`, `subject`, `body_html`, `category`, `is_active`, `created_by`, `created_at`, `updated_at`) VALUES
('1', 'Welcome Letter', 'Welcome to {company_name}', '<div style=\"font-family:Arial,sans-serif;max-width:600px;margin:0 auto;\"><div style=\"background:linear-gradient(135deg,#0e6977,#148f9f);padding:20px;text-align:center;border-radius:8px 8px 0 0;\"><h1 style=\"color:#fff;margin:0;font-size:24px;\">Welcome</h1></div><div style=\"padding:30px;background:#fff;border:1px solid #e0e0e0;\"><p>Dear {client_name},</p><p>Welcome to our services. We look forward to working with you.</p><p>Should you have any questions, please do not hesitate to contact us.</p><p style=\"margin-top:30px;\">Kind Regards,<br><strong>{user_name}</strong></p></div><div style=\"background:#f5f5f5;padding:15px;text-align:center;font-size:12px;color:#888;border-radius:0 0 8px 8px;\">SmartWeigh</div></div>', 'General', '1', NULL, '2026-02-28 21:56:14', '2026-04-24 07:30:04'),
('2', 'EMP201 Reminder', 'EMP201 Return Reminder - {month} {year}', '<div style=\"font-family:Arial,sans-serif;max-width:600px;margin:0 auto;\"><div style=\"background:linear-gradient(135deg,#0e6977,#148f9f);padding:20px;text-align:center;border-radius:8px 8px 0 0;\"><h1 style=\"color:#fff;margin:0;font-size:22px;\">EMP201 Return Reminder</h1></div><div style=\"padding:30px;background:#fff;border:1px solid #e0e0e0;\"><p>Dear {client_name},</p><p>This is a friendly reminder that your EMP201 monthly return is due for submission.</p><p>Please ensure all payroll declarations are submitted timeously to avoid penalties.</p><p style=\"margin-top:30px;\">Kind Regards,<br><strong>{user_name}</strong></p></div><div style=\"background:#f5f5f5;padding:15px;text-align:center;font-size:12px;color:#888;border-radius:0 0 8px 8px;\">SmartWeigh</div></div>', 'Compliance', '1', NULL, '2026-02-28 21:56:14', '2026-02-28 21:56:14'),
('3', 'Tax Compliance Notice', 'Tax Compliance Status Update - {client_name}', '<div style=\"font-family:Arial,sans-serif;max-width:600px;margin:0 auto;\"><div style=\"background:linear-gradient(135deg,#0e6977,#148f9f);padding:20px;text-align:center;border-radius:8px 8px 0 0;\"><h1 style=\"color:#fff;margin:0;font-size:22px;\">Tax Compliance Notice</h1></div><div style=\"padding:30px;background:#fff;border:1px solid #e0e0e0;\"><p>Dear {client_name},</p><p>Please be advised of the following compliance matters that require your attention.</p><p>Please contact our office at your earliest convenience to discuss.</p><p style=\"margin-top:30px;\">Kind Regards,<br><strong>{user_name}</strong></p></div><div style=\"background:#f5f5f5;padding:15px;text-align:center;font-size:12px;color:#888;border-radius:0 0 8px 8px;\">SmartWeigh</div></div>', 'Compliance', '1', NULL, '2026-02-28 21:56:14', '2026-02-28 21:56:14'),
('4', 'General Notice', 'Important Notice - {company_name}', '<div style=\"font-family:Arial,sans-serif;max-width:600px;margin:0 auto;\"><div style=\"background:linear-gradient(135deg,#0e6977,#148f9f);padding:20px;text-align:center;border-radius:8px 8px 0 0;\"><h1 style=\"color:#fff;margin:0;font-size:22px;\">Notice</h1></div><div style=\"padding:30px;background:#fff;border:1px solid #e0e0e0;\"><p>Dear {client_name},</p><p></p><p style=\"margin-top:30px;\">Kind Regards,<br><strong>{user_name}</strong></p></div><div style=\"background:#f5f5f5;padding:15px;text-align:center;font-size:12px;color:#888;border-radius:0 0 8px 8px;\">SmartWeigh</div></div>', 'General', '1', NULL, '2026-02-28 21:56:14', '2026-02-28 21:56:14'),
('5', 'Bank Statement Request – Friendly', '{current_month} {current_year} Bank Statement Required – {company_name}', '<p><strong>{company_name}</strong><br>{client_address}</p><p><strong>SUBJECT:</strong> {current_month} {current_year} Bank Statement Required</p><p>Dear {contact_title} {contact_first_name} ({contact_known_as}),</p><p>I hope you are well.</p><p>As part of our ongoing monthly accounting and compliance process, we kindly request that you please forward us your <strong>{current_month} {current_year} bank statement</strong> at your earliest convenience.</p><p>Receiving the statement timeously allows us to ensure that your bookkeeping, reconciliations, and statutory submissions are processed accurately and without delay.</p><p>Kindly email the bank statement to <strong>{sender_email}</strong> once available.</p><p>If there are multiple accounts, please include all relevant statements for {current_month} {current_year}.</p><p>Should you have any questions or require assistance retrieving the statement from your bank, please feel free to let us know &mdash; we are always happy to assist.</p><p>Thank you for your continued cooperation and trust in our services.</p>', 'Compliance', '1', '1', '2026-03-01 16:45:35', '2026-03-01 23:53:41'),
('6', 'Bank Statement Request – Overdue', 'FOLLOW-UP: Outstanding {current_month} {current_year} Bank Statement – {company_name}', '<p><strong>{company_name}</strong><br>{client_address}</p><p><strong>SUBJECT:</strong> FOLLOW-UP: Outstanding {current_month} {current_year} Bank Statement</p><p>Dear {contact_title} {contact_first_name} ({contact_known_as}),</p><p>I hope you are well.</p><p>We have not yet received your <strong>{current_month} {current_year} bank statement</strong> for <strong>{company_name}</strong>.</p><p>We are currently unable to finalise your accounting records and statutory submissions without it, which may result in compliance delays.</p><p>Kindly email the statement to <strong>{sender_email}</strong> as soon as possible to avoid any delays.</p><p>If there are multiple bank accounts, please include all relevant statements.</p><p>Please confirm once sent.</p><p>Thank you for your immediate attention to this matter.</p>', 'Compliance', '1', '1', '2026-03-01 16:45:35', '2026-03-01 23:53:41'),
('7', 'Bank Statement Request – Urgent', 'URGENT: Outstanding Bank Statement – Action Required – {company_name}', '<p><strong>{company_name}</strong><br>{client_address}</p><p><strong>SUBJECT:</strong> URGENT: Outstanding Bank Statement – Action Required</p><p>Dear {contact_title} {contact_first_name} ({contact_known_as}),</p><p>This is an <strong>urgent reminder</strong> regarding the outstanding bank statement for <strong>{company_name}</strong> ({client_code}).</p><p>We have not received your <strong>{current_month} {current_year} bank statement</strong> despite previous requests. Without this document, we are unable to:</p><ul><li>Complete monthly bookkeeping and reconciliations</li><li>Submit VAT returns timeously</li><li>Process EMP201 and other statutory obligations</li></ul><p><strong>Failure to submit may result in penalties and interest from SARS.</strong></p><p>Kindly email all outstanding bank statements to <strong>{sender_email}</strong> as a matter of urgency.</p><p>If you are experiencing any difficulty obtaining the statement from your bank, please let us know immediately so we can assist.</p><p>Thank you for your urgent attention.</p>', 'Compliance', '1', '1', '2026-03-01 16:45:35', '2026-03-01 23:53:41'),
('8', 'Document Request', 'ATP Services | Document as Requested', '<p data-start=\"249\" data-end=\"268\"><span style=\"font-size: 16px;\">Dear {contact_first_name},</span></p><p data-start=\"187\" data-end=\"210\"><span style=\"font-size: 16px;\">I trust you are well.</span></p><p data-start=\"212\" data-end=\"366\"><span style=\"font-size: 16px;\">Please find the requested documents attached for your review. Should you require any clarification or further information, I remain available to assist.</span></p><p data-start=\"368\" data-end=\"413\"><span style=\"font-size: 16px;\">Kindly confirm receipt at your convenience.</span></p><p data-start=\"270\" data-end=\"296\"><span style=\"font-size: 16px;\">\r\n\r\n\r\n</span></p><p data-start=\"415\" data-end=\"491\"><span style=\"font-size: 16px;\">We appreciate the opportunity to assist and look forward to your feedback.</span></p><p><span style=\"font-size: 16px;\">\r\n\r\n\r\n\r\n\r\n</span></p><p data-start=\"610\" data-end=\"728\"><span style=\"font-size: 16px;\">Warm regards,</span><br data-start=\"623\" data-end=\"626\"><br></p>', 'General', '1', '1', '2026-03-10 03:11:07', '2026-04-24 07:21:20'),
('9', 'Send Invoice to Client', 'Invoice {{invoice_number}} from {{company_name}}', '<p class=\"isSelectedEnd\">Dear&nbsp; &nbsp;{contact_title}&nbsp;&nbsp;{contact_first_name} {contact_last_name}</p><p class=\"isSelectedEnd\">I hope you are well.</p><p class=\"isSelectedEnd\">Please find attached your invoice <strong>{{invoice_number}}</strong> dated <strong>{{invoice_date}}</strong>, relating to <strong>{{service_description}}</strong>.</p><p class=\"isSelectedEnd\">💼 <strong>Invoice Summary</strong><br>• Amount Due: <strong>R {{amount_due}}</strong><br>• Due Date: <strong>{{due_date}}</strong></p><p class=\"isSelectedEnd\">We kindly request that payment be made on or before the due date to ensure uninterrupted service.</p><p class=\"isSelectedEnd\">For your convenience, our banking details are provided below:</p><p class=\"isSelectedEnd\">🏦 <strong>Banking Details</strong><br>Account Name: {{company_name}}<br>Bank: {{bank_name}}<br>Account Number: {{account_number}}<br>Branch Code: {{branch_code}}<br>Reference: <strong>{{invoice_number}}</strong></p><p class=\"isSelectedEnd\">Once payment has been made, please forward proof of payment to <strong>{{accounts_email}}</strong> so we can allocate it promptly to your account.</p><p class=\"isSelectedEnd\">Should you have any queries regarding this invoice, please feel free to contact us — we are always happy to assist.</p><p class=\"isSelectedEnd\">Thank you for your continued support and valued business.</p><p>Warm regards,<br><strong>{{your_name}}</strong><br>{{your_position}}<br><strong>{{company_name}}</strong><br>📞 {{contact_number}}<br>📧 {{company_email}}</p><p><br></p>', 'Invoicing', '1', '1', '2026-03-22 22:58:16', '2026-03-22 22:58:16'),
('10', 'Appointment Confirmation', 'Appointment Confirmation - {appointment_date}', '<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"><tr><td bgcolor=\"#0d3d56\" style=\"background-color:#0d3d56;padding:28px 24px;text-align:center;border-radius:8px 8px 0 0;\"><p style=\"margin:0 0 8px;font-size:32px;color:#ffffff;\">&#10003;</p><h1 style=\"color:#ffffff;margin:0;font-size:22px;font-weight:700;\">Appointment Confirmed</h1><p style=\"color:#aaccdd;margin:6px 0 0;font-size:13px;\">Your appointment has been booked successfully</p></td></tr></table><div style=\"padding:24px 0;\"><p>Dear {contact_title} {contact_first_name} {contact_last_name},</p><p>Thank you for scheduling your appointment with <strong>{company_name}</strong>. We are pleased to confirm the following details:</p><table cellpadding=\"8\" cellspacing=\"0\" border=\"0\" style=\"width:100%;border:1px solid #ddd;border-radius:6px;margin:16px 0;border-collapse:collapse;\"><tr style=\"background-color:#0d3d56;\"><td colspan=\"2\" style=\"padding:10px 16px;color:#ffffff;font-weight:700;font-size:13px;text-transform:uppercase;letter-spacing:1px;\">Appointment Details</td></tr><tr><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;color:#888;font-size:12px;font-weight:700;text-transform:uppercase;width:120px;\">Service</td><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;font-weight:600;color:#333;\">{service_name}</td></tr><tr><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;color:#888;font-size:12px;font-weight:700;text-transform:uppercase;width:120px;\">Date</td><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;font-weight:600;color:#333;\">{appointment_date}</td></tr><tr><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;color:#888;font-size:12px;font-weight:700;text-transform:uppercase;width:120px;\">Time</td><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;font-weight:600;color:#333;\">{appointment_time}</td></tr><tr><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;color:#888;font-size:12px;font-weight:700;text-transform:uppercase;width:120px;\">Duration</td><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;font-weight:600;color:#333;\">{duration}</td></tr><tr><td style=\"padding:10px 16px;color:#888;font-size:12px;font-weight:700;text-transform:uppercase;width:120px;\">Consultant</td><td style=\"padding:10px 16px;font-weight:600;color:#333;\">{staff_name}</td></tr></table>{location_section}{attendee_list}{amount_section}{notes_section}<p>Should you need to reschedule or cancel, please do not hesitate to contact us.</p><p>We look forward to meeting with you.</p><p>Kind regards,</p></div>', 'Appointments', '1', '1', '2026-03-23 03:11:01', '2026-03-23 03:33:23'),
('11', 'Appointment Reminder', 'Appointment Reminder - {appointment_date}', '<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"><tr><td bgcolor=\"#1a5276\" style=\"background-color:#1a5276;padding:28px 24px;text-align:center;border-radius:8px 8px 0 0;\"><p style=\"margin:0 0 8px;font-size:32px;color:#ffffff;\">&#128276;</p><h1 style=\"color:#ffffff;margin:0;font-size:22px;font-weight:700;\">Appointment Reminder</h1><p style=\"color:#aaccdd;margin:6px 0 0;font-size:13px;\">Your appointment is coming up soon</p></td></tr></table><div style=\"padding:24px 0;\"><p>Dear {contact_title} {contact_first_name} {contact_last_name},</p><p>This is a friendly reminder about your upcoming appointment with <strong>{company_name}</strong>.</p><table cellpadding=\"8\" cellspacing=\"0\" border=\"0\" style=\"width:100%;border:1px solid #ddd;border-radius:6px;margin:16px 0;border-collapse:collapse;\"><tr style=\"background-color:#1a5276;\"><td colspan=\"2\" style=\"padding:10px 16px;color:#ffffff;font-weight:700;font-size:13px;text-transform:uppercase;letter-spacing:1px;\">Appointment Reminder</td></tr><tr><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;color:#888;font-size:12px;font-weight:700;text-transform:uppercase;width:120px;\">Service</td><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;font-weight:600;color:#333;\">{service_name}</td></tr><tr><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;color:#888;font-size:12px;font-weight:700;text-transform:uppercase;width:120px;\">Date</td><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;font-weight:600;color:#333;\">{appointment_date}</td></tr><tr><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;color:#888;font-size:12px;font-weight:700;text-transform:uppercase;width:120px;\">Time</td><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;font-weight:600;color:#333;\">{appointment_time}</td></tr><tr><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;color:#888;font-size:12px;font-weight:700;text-transform:uppercase;width:120px;\">Duration</td><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;font-weight:600;color:#333;\">{duration}</td></tr><tr><td style=\"padding:10px 16px;color:#888;font-size:12px;font-weight:700;text-transform:uppercase;width:120px;\">Consultant</td><td style=\"padding:10px 16px;font-weight:600;color:#333;\">{staff_name}</td></tr></table>{location_section}{attendee_list}<p>Should you need to reschedule or cancel, please contact us as soon as possible.</p><p>We look forward to seeing you.</p><p>Kind regards,</p></div>', 'Appointments', '1', '1', '2026-03-23 03:11:01', '2026-03-23 03:33:23'),
('12', 'Appointment Cancellation', 'Appointment Cancelled - {appointment_date}', '<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"><tr><td bgcolor=\"#922b21\" style=\"background-color:#922b21;padding:28px 24px;text-align:center;border-radius:8px 8px 0 0;\"><p style=\"margin:0 0 8px;font-size:32px;color:#ffffff;\">&#10005;</p><h1 style=\"color:#ffffff;margin:0;font-size:22px;font-weight:700;\">Appointment Cancelled</h1><p style=\"color:#eecccc;margin:6px 0 0;font-size:13px;\">Your appointment has been cancelled</p></td></tr></table><div style=\"padding:24px 0;\"><p>Dear {contact_title} {contact_first_name} {contact_last_name},</p><p>We regret to inform you that your appointment with <strong>{company_name}</strong> has been cancelled.</p><table cellpadding=\"8\" cellspacing=\"0\" border=\"0\" style=\"width:100%;border:1px solid #ddd;border-radius:6px;margin:16px 0;border-collapse:collapse;\"><tr style=\"background-color:#922b21;\"><td colspan=\"2\" style=\"padding:10px 16px;color:#ffffff;font-weight:700;font-size:13px;text-transform:uppercase;letter-spacing:1px;\">Cancelled Appointment</td></tr><tr><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;color:#888;font-size:12px;font-weight:700;text-transform:uppercase;width:120px;\">Service</td><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;font-weight:600;color:#333;\">{service_name}</td></tr><tr><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;color:#888;font-size:12px;font-weight:700;text-transform:uppercase;width:120px;\">Date</td><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;font-weight:600;color:#333;\">{appointment_date}</td></tr><tr><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;color:#888;font-size:12px;font-weight:700;text-transform:uppercase;width:120px;\">Time</td><td style=\"padding:10px 16px;border-bottom:1px solid #f0f0f0;font-weight:600;color:#333;\">{appointment_time}</td></tr><tr><td style=\"padding:10px 16px;color:#888;font-size:12px;font-weight:700;text-transform:uppercase;width:120px;\">Consultant</td><td style=\"padding:10px 16px;font-weight:600;color:#333;\">{staff_name}</td></tr></table>{location_section}{cancellation_reason}<p>We sincerely apologise for any inconvenience caused. Should you wish to rebook, please do not hesitate to contact us.</p><p>Kind regards,</p></div>', 'Appointments', '1', '1', '2026-03-23 03:11:01', '2026-03-23 03:33:23'),
('13', 'Customer Statement', 'Customer Statement of Account', '<p class=\"isSelectedEnd\">Dear&nbsp;<span data-placeholder-token=\"true\" class=\"text-token-text-primary cursor-text rounded-sm\">{company_name}</span>,</p><p class=\"isSelectedEnd\">I hope this message finds you well.</p><p class=\"isSelectedEnd\">Please find attached your latest statement of account for your review. The statement reflects all transactions on your account up to {current_month}, including any outstanding balances.</p><p class=\"isSelectedEnd\">Kindly review the details and let us know if you have any questions or require further clarification. </p><p class=\"isSelectedEnd\">If you have already made payment, please disregard this message or forward us the proof of payment so we can update our records accordingly.</p><p class=\"isSelectedEnd\">Thank you for your continued support.</p><p>Best regards,</p>', 'Invoicing', '1', '3', '2026-05-06 12:36:05', '2026-05-07 10:34:49');
