INSERT INTO `cims_ref_company_types` (`id`, `type_code`, `type_name`, `type_short`, `type_description`, `tooltip`, `is_active`) VALUES
('1', '06', 'External Company', 'External', 'A foreign company operating in South Africa. Must register with CIPC to conduct business locally.', 'Foreign company registered to operate in SA', '1'),
('2', '07', 'Private Company (Pty) Ltd', 'Pty', 'Most common business structure. Separate legal entity with limited liability for shareholders. Cannot offer shares to the public. Ideal for SMEs and startups.', 'Limited liability company - most common for SMEs', '1'),
('3', '08', 'Non-Profit Company (NPC)', 'NPC', 'Established for public benefit, social, cultural, religious or charitable purposes. Surplus income must be reinvested - no profit distribution allowed. Requires minimum 3 directors.', 'For charitable/public benefit - no profit distribution', '1'),
('4', '09', 'State Owned Company (SOC)', 'SOC', 'Company owned by the South African government. Provides essential services like electricity, water and transport. Subject to same legal requirements as other companies.', 'Government-owned entity providing public services', '1'),
('5', '10', 'Public Company (Ltd)', 'Ltd', 'Large-scale business structure that can offer shares to the general public. Usually listed on stock exchanges. Requires minimum 3 directors and 7 shareholders.', 'Can offer shares publicly - for large businesses', '1'),
('6', '11', 'Personal Liability Company (Inc)', 'Inc', 'Used by professionals like lawyers, doctors and accountants. Directors are jointly and severally liable for company debts incurred during their tenure.', 'Directors personally liable for debts - for professionals', '1'),
('7', '21', 'Incorporated Company', 'Inc', 'A company incorporated under previous legislation. These entities continue to exist under the current Companies Act.', 'Company incorporated under previous legislation', '1'),
('8', '23', 'Close Corporation (CC)', 'CC', 'No longer available for new registrations since 2011. Existing CCs remain valid. Similar to Pty but with members instead of shareholders. Maximum 10 natural person members.', 'Legacy structure - no new registrations since 2011', '1'),
('9', '24', 'Co-operative', 'Co-op', 'An autonomous association of persons united to meet common economic, social, and cultural needs through a jointly-owned democratic enterprise.', 'Member-owned democratic enterprise', '1'),
('10', '25', 'Primary Co-operative', 'Primary Co-op', 'A co-operative formed by natural persons to provide services directly to its members. First level of co-operative structure.', 'Direct member services co-operative', '1'),
('11', '26', 'Secondary Co-operative', 'Secondary Co-op', 'A co-operative formed by two or more primary co-operatives to provide services to its member co-operatives.', 'Co-operative of primary co-operatives', '1');
