INSERT INTO `nexcore_account_templates` (`id`, `template_name`, `industry_type`, `description`, `is_default`, `is_active`, `created_at`, `updated_at`) VALUES
('6', 'General Trader', 'general_trading', 'Standard chart of accounts for a general trading business. Suitable for most non-specialised companies including retail, wholesale, distribution, and general services. SA VAT and statutory compliance accounts included.', '0', '1', '2026-05-13 07:16:25', '2026-05-13 07:16:25'),
('7', 'Medical Practitioner', 'medical_practitioner', 'Comprehensive chart of accounts for a Medical Practitioner / General Practitioner practice. Includes consultation, dispensing, procedures, pathology, occupational health, drip services cost centres. Revenue split by service type. SA VAT and statutory compliance accounts.', '0', '1', '2026-05-13 07:39:50', '2026-05-13 07:39:50'),
('8', 'Mechanical Workshop', 'mechanical_workshop', 'Comprehensive chart of accounts for a mechanical workshop, tyre fitment, and auto service centre. Includes labour, parts, tyres, batteries, lubricants, alignment, balancing, diagnostics, and fleet servicing cost centres. SA VAT and statutory compliance accounts.', '0', '1', '2026-05-13 07:44:17', '2026-05-13 07:44:17'),
('9', 'Tyre Shop', 'tyre_shop', 'Chart of accounts for a dedicated tyre retail and fitment centre. Covers new and used tyre sales by vehicle category, fitment, balancing, alignment, puncture repairs, mag wheels, batteries, and fleet tyre management. SA VAT and statutory compliance accounts.', '0', '1', '2026-05-13 07:48:46', '2026-05-13 07:48:46'),
('10', 'Accounting & Bookkeeping Practice', 'Professional Services', 'Chart of accounts for accounting firms, bookkeeping practices, tax practitioners, and financial service providers', '0', '1', '2026-05-13 07:53:13', '2026-05-13 07:53:13'),
('11', 'Legal / Law Practice', 'Professional Services', 'Chart of accounts for attorneys, law firms, advocates, conveyancers, notaries, and legal practitioners', '0', '1', '2026-05-13 07:56:57', '2026-05-13 07:56:57'),
('12', 'Aggregate, Concrete & Stone Mining', 'Mining & Quarrying', 'Chart of accounts for quarries, aggregate producers, ready-mix concrete plants, stone crushers, and mining operations', '0', '1', '2026-05-13 08:01:37', '2026-05-13 08:01:37'),
('13', 'Asphalt Premix Manufacturing & Paving', 'Construction & Manufacturing', 'Chart of accounts for asphalt plants, premix manufacturers, paving contractors, road construction, and surfacing operations', '0', '1', '2026-05-13 08:06:30', '2026-05-13 08:06:30'),
('14', 'Dental Practice', 'Healthcare', 'Chart of accounts for dentists, dental surgeons, orthodontists, oral hygienists, and dental clinics', '0', '1', '2026-05-13 08:10:30', '2026-05-13 08:10:30'),
('15', 'Optometrist / Optical Practice', 'Healthcare', 'Chart of accounts for optometrists, opticians, optical dispensers, and eye care practices', '0', '1', '2026-05-13 08:17:06', '2026-05-13 08:17:06'),
('16', 'Box Manufacturing & Packaging', 'Manufacturing', 'Chart of accounts for corrugated box manufacturers, cardboard packaging, screen printing, die cutting, and packaging converters', '0', '1', '2026-05-13 08:22:25', '2026-05-13 08:22:25'),
('17', 'Auto Electrical Workshop', 'Automotive', 'Chart of accounts for auto electrical workshops including starter/alternator repairs, wiring harness work, battery services, diagnostic testing, and vehicle electrical component sales.', '0', '1', '2026-05-13 08:40:10', '2026-05-13 08:40:10'),
('18', 'SA Standard Business', 'General', 'Comprehensive SA chart of accounts covering 90% of business types. Income Statement first (1000-3000), then Balance Sheet (4000-6000), with Suspense (9000).', '1', '1', '2026-05-23 02:45:16', '2026-05-23 02:45:16');
