INSERT INTO `nexcore_system_bank_account_types` (`id`, `name`, `code`, `description`, `is_active`, `is_deleted`, `created_at`, `updated_at`) VALUES
('1', 'Current Account', 'CUR', 'Standard transactional bank account used for day-to-day deposits, withdrawals, and payments. Also known as a cheque account.', '1', '0', '2026-05-17 23:04:23', '2026-05-17 23:04:23'),
('2', 'Savings Account', 'SAV', 'Interest-bearing account designed for accumulating funds, typically with limited transaction capabilities.', '1', '0', '2026-05-17 23:04:23', '2026-05-17 23:04:23'),
('3', 'Transmission Account', 'TRAN', 'A basic transactional account for receiving and making payments, commonly used for salary deposits in South Africa.', '1', '0', '2026-05-17 23:04:23', '2026-05-17 23:04:23'),
('4', 'Fixed Deposit', 'FIX', 'A time-bound deposit account where funds are locked for a specified period at a fixed interest rate.', '1', '0', '2026-05-17 23:04:23', '2026-05-17 23:04:23'),
('5', 'Call Deposit', 'CALL', 'A flexible investment account where funds earn interest but can be withdrawn on demand without penalties.', '1', '0', '2026-05-17 23:04:23', '2026-05-17 23:04:23'),
('6', 'Money Market Account', 'MM', 'A higher-interest account that invests in short-term money market instruments, typically requiring a higher minimum balance.', '1', '0', '2026-05-17 23:04:23', '2026-05-17 23:04:23'),
('7', 'Business Account', 'BUS', 'A transactional account specifically designed for business operations, with features like bulk payments and merchant facilities.', '1', '0', '2026-05-17 23:04:23', '2026-05-17 23:04:23'),
('8', 'Trust Account', 'TRST', 'An account held by a trustee on behalf of beneficiaries, governed by the Trust Property Control Act in South Africa.', '1', '0', '2026-05-17 23:04:23', '2026-05-17 23:04:23'),
('9', 'Bond Account', 'BOND', 'A home loan or mortgage account used for property financing, where the property serves as collateral.', '1', '0', '2026-05-17 23:04:23', '2026-05-17 23:04:23'),
